import re
from datetime import datetime

_DATE_FORMATS = ("%Y-%m-%d", "%m/%d/%Y", "%Y-%m-%dT%H:%M:%S")
_OPT_OUT_VALUES = {"y", "yes", "true", "1"}
_DIGITS = "0123456789"
_ANGLE_RE = re.compile(r"<([^<>]*)>")
_ZIP_PLUS4_RE = re.compile(r"[0-9]{5}-[0-9]{4}")
_TAG_SPLIT_RE = re.compile(r"[;,]")


def _is_ascii_digits(s):
    return bool(s) and all(c in _DIGITS for c in s)


def _normalize_email(raw):
    s = raw.strip()
    m = _ANGLE_RE.search(s)
    if m:
        s = m.group(1)
    s = s.strip().lower()
    if s.count("@") == 1:
        local, domain = s.split("@")
        if domain in ("gmail.com", "googlemail.com"):
            local = local.replace(".", "").split("+", 1)[0]
            domain = "gmail.com"
            s = f"{local}@{domain}"
    return s


def _is_valid_email(e):
    if e.count("@") != 1:
        return False
    local, domain = e.split("@")
    return (
        bool(local)
        and "." in domain
        and not domain.startswith(".")
        and not domain.endswith(".")
    )


def _normalize_phone(raw):
    s = raw.lower()
    cut = len(s)
    for marker in ("ext", "x", "#"):
        i = s.find(marker)
        if i != -1:
            cut = min(cut, i)
    digits = "".join(c for c in s[:cut] if c in _DIGITS)
    if len(digits) == 11 and digits[0] == "1":
        digits = digits[1:]
    return digits


def _is_valid_phone(d):
    return len(d) == 10 and d[0] not in "01"


def _normalize_zip(raw):
    s = raw.strip()
    if _ZIP_PLUS4_RE.fullmatch(s):
        s = s.split("-", 1)[0]
    if len(s) == 4 and _is_ascii_digits(s):
        s = "0" + s
    if len(s) == 5 and _is_ascii_digits(s):
        return s
    return ""


def _normalize_name(raw):
    s = raw.strip()
    if s.isupper() or s.islower():
        s = s.title()
    return s


def _parse_updated(raw):
    s = raw.strip()
    for fmt in _DATE_FORMATS:
        try:
            return datetime.strptime(s, fmt)
        except ValueError:
            pass
    return None


def _is_opted_out(raw):
    return raw.strip().lower() in _OPT_OUT_VALUES


def _parse_tags(raw):
    return {p.strip().lower() for p in _TAG_SPLIT_RE.split(raw) if p.strip()}


def _pick(members, field):
    """Pick the normalized value of `field` from the group's rows.

    Preference: manual source, then most recent `updated`, then earlier input row.
    Only rows with a non-empty normalized value qualify.
    """
    candidates = [m for m in members if m[field]]
    if not candidates:
        return ""
    # Stable sorts applied from least to most significant key.
    candidates.sort(key=lambda m: m["idx"])
    candidates.sort(
        key=lambda m: m["ts"] if m["ts"] is not None else datetime.min,
        reverse=True,
    )
    candidates.sort(key=lambda m: 0 if m["manual"] else 1)
    return candidates[0][field]


def dedupe_contacts(rows):
    """Deduplicate CRM contact rows per the data person's rules.

    Returns a list of dicts (one per person, ordered by each person's
    earliest input row) with keys: first_name, last_name, zip, email,
    phone, source, tags, opted_out, updated.
    """
    # Step 1: normalize each row and drop rows with no valid email or phone.
    records = []
    for idx, row in enumerate(rows):
        email = _normalize_email(row.get("email", ""))
        if not _is_valid_email(email):
            email = ""
        phone = _normalize_phone(row.get("phone", ""))
        if not _is_valid_phone(phone):
            phone = ""
        if not email and not phone:
            continue

        source = row.get("source", "").strip().lower()
        records.append({
            "idx": idx,
            "email": email,
            "phone": phone,
            "first_name": _normalize_name(row.get("first_name", "")),
            "last_name": _normalize_name(row.get("last_name", "")),
            "zip": _normalize_zip(row.get("zip", "")),
            "source": source,
            "manual": source == "manual",
            "ts": _parse_updated(row.get("updated", "")),
            "tags": _parse_tags(row.get("tags", "")),
            "opted_out": _is_opted_out(row.get("opted_out", "")),
        })

    # Step 2: union-find over records; matches are transitive.
    parent = list(range(len(records)))

    def find(x):
        while parent[x] != x:
            parent[x] = parent[parent[x]]
            x = parent[x]
        return x

    def union(a, b):
        ra, rb = find(a), find(b)
        if ra != rb:
            if ra < rb:
                parent[rb] = ra
            else:
                parent[ra] = rb

    email_seen = {}
    phone_seen = {}
    for pos, rec in enumerate(records):
        if rec["email"]:
            key = rec["email"]
            if key in email_seen:
                union(email_seen[key], pos)
            else:
                email_seen[key] = pos
        if rec["phone"] and rec["last_name"]:
            key = (rec["phone"], rec["last_name"].casefold())
            if key in phone_seen:
                union(phone_seen[key], pos)
            else:
                phone_seen[key] = pos

    # Step 3: group rows; groups ordered by earliest input row.
    groups = {}
    order = []
    for pos in range(len(records)):
        root = find(pos)
        if root not in groups:
            groups[root] = []
            order.append(root)
        groups[root].append(records[pos])

    # Step 4: build one output record per person.
    result = []
    for root in order:
        members = groups[root]
        out = {
            "first_name": _pick(members, "first_name"),
            "last_name": _pick(members, "last_name"),
            "zip": _pick(members, "zip"),
            "email": _pick(members, "email"),
            "phone": _pick(members, "phone"),
            "source": _pick(members, "source"),
        }
        all_tags = set().union(*(m["tags"] for m in members))
        out["tags"] = ";".join(sorted(all_tags))
        out["opted_out"] = "Y" if any(m["opted_out"] for m in members) else "N"
        dates = [m["ts"] for m in members if m["ts"] is not None]
        out["updated"] = max(dates).strftime("%Y-%m-%d") if dates else ""
        result.append(out)

    return result
